"""Normalization into a lightweight Perses-style prioritized normal form."""

from __future__ import annotations

import copy
from typing import Iterable

from reduction.grammar import Grammar, GrammarRule, RuleType


class PNFNormalizer:
    """Normalize grammars into the constrained form expected by reducers.

    The grammar model in this repository is intentionally lightweight, so the
    normalizer focuses on structural cleanups that are meaningful for the
    reducers:
    - remove unreachable productions
    - inline alias rules with a single alternative
    - factor quantified rules so each quantifier wraps one named symbol
    - rewrite direct left/right recursion into iterative helper rules
    """

    def __init__(self) -> None:
        self._name_counter = 0

    def normalize(self, grammar: Grammar) -> Grammar:
        """Return a normalized deep copy of ``grammar``."""
        normalized = self._clone_grammar(grammar)

        for _ in range(8):
            before = self._signature(normalized)
            self._extract_nested_rules(normalized)
            self._normalize_quantified_rules(normalized)
            self._inline_single_symbol_rules(normalized)
            self._remove_direct_recursion(normalized)
            self._eliminate_unreachable(normalized)
            after = self._signature(normalized)
            if after == before:
                break

        return normalized

    def _clone_grammar(self, grammar: Grammar) -> Grammar:
        clone = Grammar(start_symbol=grammar.start_symbol)
        for rule in grammar.rules.values():
            clone.add_rule(copy.deepcopy(rule))
        return clone

    def _signature(self, grammar: Grammar) -> tuple:
        signature = []
        for name in sorted(grammar.rules):
            rule = grammar.rules[name]
            symbols = []
            for symbol in rule.symbols:
                if isinstance(symbol, GrammarRule):
                    symbols.append(("rule", symbol.name, symbol.rule_type.value))
                else:
                    symbols.append(("sym", symbol))
            signature.append((name, rule.rule_type.value, tuple(symbols)))
        return tuple(signature)

    def _unique_name(self, grammar: Grammar, prefix: str) -> str:
        base = prefix.replace("-", "_")
        name = base
        while name in grammar.rules:
            self._name_counter += 1
            name = f"{base}_{self._name_counter}"
        return name

    def _extract_nested_rules(self, grammar: Grammar) -> None:
        """Replace nested GrammarRule objects with named helper rules."""
        pending: list[GrammarRule] = []
        for rule in list(grammar.rules.values()):
            new_symbols: list[str] = []
            changed = False
            for index, symbol in enumerate(rule.symbols):
                if isinstance(symbol, GrammarRule):
                    helper_name = self._unique_name(grammar, f"{rule.name}__nested_{index}")
                    nested = copy.deepcopy(symbol)
                    nested.name = helper_name
                    pending.append(nested)
                    new_symbols.append(helper_name)
                    changed = True
                else:
                    new_symbols.append(symbol)
            if changed:
                rule.symbols = new_symbols

        for helper in pending:
            grammar.add_rule(helper)

    def _normalize_quantified_rules(self, grammar: Grammar) -> None:
        """Ensure quantifiers wrap one named rule."""
        for rule in list(grammar.rules.values()):
            if not rule.is_quantified():
                continue
            if len(rule.symbols) == 1 and isinstance(rule.symbols[0], str):
                continue

            item_name = self._unique_name(grammar, f"{rule.name}__item")
            grammar.add_rule(
                GrammarRule(
                    name=item_name,
                    rule_type=RuleType.SEQUENCE,
                    symbols=[symbol for symbol in rule.symbols if isinstance(symbol, str)],
                )
            )
            rule.symbols = [item_name]

    def _inline_single_symbol_rules(self, grammar: Grammar) -> None:
        """Inline alias rules like A -> B when that does not preserve cycles."""
        while True:
            alias: tuple[str, str] | None = None
            for rule in grammar.rules.values():
                if rule.name == grammar.start_symbol:
                    continue
                if rule.is_quantified():
                    continue
                if len(rule.symbols) != 1:
                    continue
                target = rule.symbols[0]
                if not isinstance(target, str):
                    continue
                if target == rule.name:
                    continue
                if self._is_reachable(grammar, target, rule.name):
                    continue
                alias = (rule.name, target)
                break

            if alias is None:
                return

            alias_name, replacement = alias
            for rule in grammar.rules.values():
                rule.symbols = [
                    replacement if symbol == alias_name else symbol
                    for symbol in rule.symbols
                ]
            grammar.rules.pop(alias_name, None)

    def _is_reachable(self, grammar: Grammar, start: str, target: str) -> bool:
        if start == target:
            return True
        stack = [start]
        seen: set[str] = set()
        while stack:
            current = stack.pop()
            if current in seen:
                continue
            seen.add(current)
            rule = grammar.rules.get(current)
            if rule is None:
                continue
            for symbol in rule.symbols:
                if not isinstance(symbol, str):
                    continue
                if symbol == target:
                    return True
                if symbol in grammar.rules:
                    stack.append(symbol)
        return False

    def _remove_direct_recursion(self, grammar: Grammar) -> None:
        """Rewrite direct left/right recursive alternations into iterative form."""
        for rule in list(grammar.rules.values()):
            if rule.rule_type != RuleType.ALTERNATION:
                continue

            left_recursive: list[list[str]] = []
            right_recursive: list[list[str]] = []
            base_symbols: list[str] = []

            for symbol in rule.symbols:
                if not isinstance(symbol, str):
                    continue
                if symbol == rule.name:
                    # Pure self recursion adds no new language in this model.
                    continue

                referenced = grammar.rules.get(symbol)
                if referenced and referenced.rule_type == RuleType.SEQUENCE and referenced.symbols:
                    if referenced.symbols[0] == rule.name and len(referenced.symbols) > 1:
                        left_recursive.append(
                            [item for item in referenced.symbols[1:] if isinstance(item, str)]
                        )
                        continue
                    if referenced.symbols[-1] == rule.name and len(referenced.symbols) > 1:
                        right_recursive.append(
                            [item for item in referenced.symbols[:-1] if isinstance(item, str)]
                        )
                        continue

                base_symbols.append(symbol)

            if not base_symbols:
                continue

            if left_recursive:
                self._rewrite_recursive_rule(
                    grammar=grammar,
                    rule=rule,
                    base_symbols=base_symbols,
                    recursive_fragments=left_recursive,
                    left_recursive=True,
                )
            elif right_recursive:
                self._rewrite_recursive_rule(
                    grammar=grammar,
                    rule=rule,
                    base_symbols=base_symbols,
                    recursive_fragments=right_recursive,
                    left_recursive=False,
                )

    def _rewrite_recursive_rule(
        self,
        grammar: Grammar,
        rule: GrammarRule,
        base_symbols: list[str],
        recursive_fragments: list[list[str]],
        left_recursive: bool,
    ) -> None:
        base_ref = self._materialize_choice(grammar, f"{rule.name}__base", base_symbols)

        fragment_refs = []
        for index, fragment in enumerate(recursive_fragments):
            fragment_ref = self._materialize_sequence(
                grammar,
                f"{rule.name}__fragment_{index}",
                fragment,
            )
            fragment_refs.append(fragment_ref)

        item_ref = self._materialize_choice(grammar, f"{rule.name}__repeat_item", fragment_refs)
        repeat_name = self._unique_name(grammar, f"{rule.name}__repeat")
        grammar.add_rule(
            GrammarRule(
                name=repeat_name,
                rule_type=RuleType.KLEENE_STAR,
                symbols=[item_ref],
            )
        )

        rule.rule_type = RuleType.SEQUENCE
        if left_recursive:
            rule.symbols = [base_ref, repeat_name]
        else:
            rule.symbols = [repeat_name, base_ref]

    def _materialize_sequence(
        self,
        grammar: Grammar,
        prefix: str,
        symbols: Iterable[str],
    ) -> str:
        filtered = [symbol for symbol in symbols if symbol]
        if len(filtered) == 1:
            return filtered[0]
        name = self._unique_name(grammar, prefix)
        grammar.add_rule(
            GrammarRule(
                name=name,
                rule_type=RuleType.SEQUENCE,
                symbols=filtered,
            )
        )
        return name

    def _materialize_choice(
        self,
        grammar: Grammar,
        prefix: str,
        symbols: Iterable[str],
    ) -> str:
        choices = []
        for symbol in symbols:
            if symbol and symbol not in choices:
                choices.append(symbol)
        if len(choices) == 1:
            return choices[0]
        name = self._unique_name(grammar, prefix)
        grammar.add_rule(
            GrammarRule(
                name=name,
                rule_type=RuleType.ALTERNATION,
                symbols=choices,
            )
        )
        return name

    def _eliminate_unreachable(self, grammar: Grammar) -> None:
        reachable: set[str] = set()
        stack = [grammar.start_symbol]

        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            rule = grammar.rules.get(name)
            if rule is None:
                continue
            for symbol in rule.symbols:
                if isinstance(symbol, str) and symbol in grammar.rules:
                    stack.append(symbol)

        grammar.rules = {
            name: rule
            for name, rule in grammar.rules.items()
            if name in reachable
        }


def normalize_to_pnf(grammar: Grammar) -> Grammar:
    """Convenience wrapper for ``PNFNormalizer``."""
    return PNFNormalizer().normalize(grammar)

